use bus_gateway::Caller;
use sdk::Refusal;
use sdk::fixture_served::{clock, echo, tick};

/// Generated by capgen: one provider per capability namespace, each answering its
/// namespace's calls for the plugin the gateway bound.
pub struct Providers<'p> {
    pub clock: &'p dyn clock::Provide,
}

/// Generated by capgen: the plugin code serving each plugin-served capability
/// namespace, each answering its namespace's calls with a host bound to its own plugin.
pub struct Served<'p> {
    pub echo: &'p dyn echo::Serve,
    pub tick: &'p dyn tick::Serve,
}

/// Generated by capgen: the served code of a host built without any; every served
/// call answers `capability_unserved`.
pub struct Unserved;

impl echo::Serve for Unserved {
    fn ping(&self, _host: &dyn sdk::fixture_served::host::Host, _n: u32) -> Result<u32, Refusal> {
        Err(Refusal::Failed {
            code: "capability_unserved".into(),
        })
    }
}

impl tick::Serve for Unserved {
    fn count(&self, _host: &dyn sdk::fixture_served::host::Host) -> Result<u32, Refusal> {
        Err(Refusal::Failed {
            code: "capability_unserved".into(),
        })
    }
}

impl Served<'static> {
    /// No served code: every served call answers `capability_unserved`.
    pub const NONE: Served<'static> = Served {
        echo: &Unserved,
        tick: &Unserved,
    };
}

/// Generated by capgen: the host one plugin calls the SDK with. It holds the
/// gateway's caller for that plugin, the providers and the served code; its fields are
/// private, so a plugin can neither build one for another id nor reach a provider.
pub struct Bound<'g, 'p> {
    caller: Caller<'g>,
    providers: &'p Providers<'p>,
    served: &'p Served<'p>,
}

impl<'g, 'p> Bound<'g, 'p> {
    /// Binds the providers to the caller the gateway bound, with no served code. Inputs:
    /// the caller and the providers. Output: the host.
    pub fn new(caller: Caller<'g>, providers: &'p Providers<'p>) -> Self {
        Self {
            caller,
            providers,
            served: &Served::NONE,
        }
    }

    /// Binds the providers and the served code to the caller the gateway bound. Inputs:
    /// the caller, the providers and the served code. Output: the host.
    pub fn serving(
        caller: Caller<'g>,
        providers: &'p Providers<'p>,
        served: &'p Served<'p>,
    ) -> Self {
        Self {
            caller,
            providers,
            served,
        }
    }
}

impl sdk::fixture_served::host::Host for Bound<'_, '_> {
    /// Calls clock.now (clock.cap) through the gateway.
    /// Inputs: the call's inputs. Output: its result or the refusal.
    fn clock_now(&self) -> Result<u64, Refusal> {
        self.caller.call(
            &clock::NOW,
            (),
            |_| clock::check_now_input(),
            |_| self.providers.clock.now(self.caller.plugin()),
            clock::check_now_output,
        )
    }

    /// Calls echo.ping (echo.cap) through the gateway.
    /// Inputs: the call's inputs. Output: its result or the refusal.
    fn echo_ping(&self, n: u32) -> Result<u32, Refusal> {
        self.caller.serve(
            &echo::PING,
            n,
            echo::check_ping_input,
            |provider, n| {
                let host = Bound {
                    caller: provider,
                    providers: self.providers,
                    served: self.served,
                };
                self.served.echo.ping(&host, n)
            },
            echo::check_ping_output,
        )
    }

    /// Calls tick.count (tick.cap) through the gateway.
    /// Inputs: the call's inputs. Output: its result or the refusal.
    fn tick_count(&self) -> Result<u32, Refusal> {
        self.caller.serve(
            &tick::COUNT,
            (),
            |_| tick::check_count_input(),
            |provider, _| {
                let host = Bound {
                    caller: provider,
                    providers: self.providers,
                    served: self.served,
                };
                self.served.tick.count(&host)
            },
            tick::check_count_output,
        )
    }
}
